create or replace function public.toolbox_issues_users(p_workspace_id uuid) returns jsonb language sql stable security definer set search_path='' as $$ select case when not private.toolbox_issues_has_access(p_workspace_id) then '[]'::jsonb else coalesce((select jsonb_agg(jsonb_build_object('id',p.id::text,'name',coalesce(p.display_name,p.email,'User'),'email',coalesce(p.email,''),'photo_thumb',null,'is_admin',coalesce(m.role='team_leader',false),'enabled',wm.active) order by coalesce(p.display_name,p.email,'')) from public.workspace_members wm join public.profiles p on p.id=wm.user_id left join public.toolbox_issues_memberships m on m.workspace_id=wm.workspace_id and m.user_id=wm.user_id where wm.workspace_id=p_workspace_id and wm.active is true),'[]'::jsonb) end $$; create or replace function public.toolbox_issues_role_assignments(p_workspace_id uuid) returns jsonb language sql stable security definer set search_path='' as $$ select case when not private.toolbox_issues_has_access(p_workspace_id) then '{}'::jsonb else coalesce((select jsonb_object_agg(m.user_id::text,m.role) from public.toolbox_issues_memberships m where m.workspace_id=p_workspace_id and m.enabled),'{}'::jsonb) end $$; create or replace function public.toolbox_issues_admin_set_role(p_workspace_id uuid,p_user_id uuid,p_role text) returns jsonb language plpgsql security definer set search_path='' as $$ begin if not private.toolbox_issues_can_configure_roles(p_workspace_id) then raise exception 'role configuration denied' using errcode='42501'; end if; if p_role not in('team_leader','secretary','standard') then raise exception 'invalid toolbox role' using errcode='22023'; end if; if not exists(select 1 from public.workspace_members wm where wm.workspace_id=p_workspace_id and wm.user_id=p_user_id and wm.active is true) then raise exception 'target user is not an active workspace member' using errcode='22023'; end if; insert into public.toolbox_issues_memberships(workspace_id,user_id,role,assigned_by) values(p_workspace_id,p_user_id,p_role,(select auth.uid())) on conflict(workspace_id,user_id) do update set role=excluded.role,enabled=true,assigned_by=excluded.assigned_by,updated_at=now(); insert into public.toolbox_issues_activity(workspace_id,entity_type,entity_id,actor_user_id,event_type,detail) values(p_workspace_id,'membership',p_user_id::text,(select auth.uid()),'role_changed',jsonb_build_object('role',p_role)); return jsonb_build_object('success',true); end $$; revoke execute on function public.toolbox_issues_users(uuid),public.toolbox_issues_role_assignments(uuid),public.toolbox_issues_admin_set_role(uuid,uuid,text) from public,anon; grant execute on function public.toolbox_issues_users(uuid),public.toolbox_issues_role_assignments(uuid),public.toolbox_issues_admin_set_role(uuid,uuid,text) to authenticated;;
